mapper.select:
SELECT participant_id, group_buy_id, member_id, quantity, participation_status
FROM GROUP_BUY_PARTICIPANT
WHERE group_buy_id = #{groupBuyId}
  AND member_id = #{memberId}
ORDER BY participant_id DESC
LIMIT 1

mapper.update:
UPDATE GROUP_BUY
SET current_quantity = current_quantity + #{quantity}
WHERE group_buy_id = #{groupBuyId}
